-- Recipe candidates imported from the owner's second-hand AI-assembled list (128 rows).
-- EVERYTHING is status 'draft' and unverified: not visible to users until a row is set to 'published'.
-- Idempotent: re-running updates descriptive columns but never touches status or verification fields.
begin;

on conflict (recipe_code) do update set
  title = excluded.title, bv_id = excluded.bv_id, source_url = excluded.source_url, up_name_raw = excluded.up_name_raw,
  series = excluded.series, summary = excluded.summary, ingredients = excluded.ingredients, dish_kind = excluded.dish_kind,
  goal_tags_raw = excluded.goal_tags_raw, kcal_claimed = excluded.kcal_claimed, kcal_basis = excluded.kcal_basis,
  minutes = excluded.minutes, verify_note = excluded.verify_note, search_text = excluded.search_text, updated_at = now();

commit;
